void ogs_sbi_client_associate(ogs_sbi_nf_instance_t *nf_instance)
{
    ogs_sbi_client_t *client = NULL;

    ogs_assert(nf_instance);

    client = nf_instance_find_client(nf_instance);//Here, OGS_OBJECT_REF is called once.
    ogs_assert(client);

    ogs_debug("[%s] NFInstance associated [%s]",
            nf_instance->nf_type ?
                OpenAPI_nf_type_ToString(nf_instance->nf_type) : "NULL",
            nf_instance->id);

    OGS_SBI_SETUP_CLIENT(nf_instance, client);//hen, OGS_OBJECT_REF is called again elsewhere.

    nf_service_associate_client_all(nf_instance);
}


void ogs_sbi_nf_instance_remove(ogs_sbi_nf_instance_t *nf_instance)
{
    ...
    if (nf_instance->client)
        ogs_sbi_client_remove(nf_instance->client);

    ogs_pool_free(&nf_instance_pool, nf_instance);
}

void ogs_sbi_client_remove(ogs_sbi_client_t *client)
{
    ...

    /* ogs_sbi_client_t is always created with reference context */
    if (OGS_OBJECT_IS_REF(client)) {
        OGS_OBJECT_UNREF(client);//But during cleanup, only one OGS_OBJECT_UNREF is invoked."
        return;
    }

    ogs_debug("CLEINT removed [%d]", client->reference_count);

    ...
}
